import React from 'react';
import CenteredHeroSection from './CenteredHeroSection';
import PhoneMockup from './PhoneMockup';
import FloatingWidgets from './FloatingWidgets';

export default function HeroSection() {
  return (
    <div>
      {/* 1. Main Centered Hero Layout with Rotating Text & Live Performance Metrics */}
      <CenteredHeroSection />

      {/* 2. Live Interactive Phone Chat Section */}
      <section className="py-16 bg-slate-50/50 border-t border-slate-100 relative overflow-hidden">
        <div className="max-w-7xl mx-auto px-6 text-center mb-12">
          <h2 className="text-2xl sm:text-3xl font-bold text-slate-900">
            Interactive Chat Preview
          </h2>
          <p className="text-sm text-slate-500 mt-2">
            Try typing a message below to test live real-time response simulation!
          </p>
        </div>

        <div className="relative flex justify-center items-center max-w-lg mx-auto px-4">
          <PhoneMockup />
          <FloatingWidgets />
        </div>
      </section>
    </div>
  );
}
